          "evidence_locator_ids": [
            "S02-E03",
            "S02-E07",
            "S02-E01"
          ],
          "interpretation": "PFAS were separated from the bulk by sorption to bubble interfaces and transfer into foam, which was harvested as foamate containing highly enriched PFAS relative to the pool liquid.",
          "reported_term": "Foam-fractionation separation of PFAS into foam/foamate"
        },
        {
          "endpoint_type": "sorption",
          "evidence_locator_ids": [
            "S02-E01",
            "S02-E08",
            "S02-E06"
          ],
          "interpretation": "A mass-balance model assuming equilibrium between bulk and bubble interface (\u0393 = K_i C_b) and steady foam formation was used to estimate the air-water interfacial sorption coefficient K_i (m) for individual PFAS species in leachate for different cosurfactants.",
          "reported_term": "Air-water interfacial partitioning coefficient K_i"
        }
      ],
